import "server-only";

import { and, eq, isNotNull } from "drizzle-orm";

import { addGroupMember, createWorkspaceUser } from "@/lib/directory";
import { getDb } from "@/lib/db";
import { signupRequest, signupRequestGroup } from "@/lib/schema";

const provisioningStatuses = ["accepted", "provisioning", "awaiting_handover"];

// The decision is one conditional update, so repeated or concurrent accepts yield one winner.
export async function acceptSignupRequest(id: string, approverDirectoryId: string) {
  const [accepted] = await getDb()
    .update(signupRequest)
    .set({ status: "accepted", acceptedAt: new Date(), approvedByDirectoryId: approverDirectoryId })
    .where(
      and(
        eq(signupRequest.id, id),
        eq(signupRequest.status, "verified"),
        isNotNull(signupRequest.workspaceEmail),
      ),
    )
    .returning({ id: signupRequest.id });
  return Boolean(accepted);
}

// Only the caller that moves accepted -> provisioning creates the account, and `attempting`
// is persisted in that same statement, so an interrupted create is never silently repeated.
// ponytail: runs inline in the accept request; #8 adds recovery of uncertain/partial runs.
export async function provisionAcceptedRequest(id: string) {
  const db = getDb();
  const [claimed] = await db
    .update(signupRequest)
    .set({ status: "provisioning", accountCreateState: "attempting" })
    .where(and(eq(signupRequest.id, id), eq(signupRequest.status, "accepted")))
    .returning({ workspaceEmail: signupRequest.workspaceEmail });
  if (!claimed?.workspaceEmail) return;

  let userId: string;
  try {
    userId = (await createWorkspaceUser(claimed.workspaceEmail)).id;
  } catch {
    // Any failure may have reached Google: keep it for reconciliation, do not repeat it.
    await db
      .update(signupRequest)
      .set({ accountCreateState: "uncertain" })
      .where(eq(signupRequest.id, id));
    return;
  }
  await db
    .update(signupRequest)
    .set({ accountCreateState: "created", googleUserId: userId })
    .where(eq(signupRequest.id, id));

  const groups = await db
    .select()
    .from(signupRequestGroup)
    .where(eq(signupRequestGroup.signupRequestId, id));
  let complete = true;
  for (const group of groups) {
    let state = "added";
    try {
      await addGroupMember(group.groupId, userId, group.role);
    } catch {
      state = "failed";
      complete = false;
    }
    await db
      .update(signupRequestGroup)
      .set({ state })
      .where(
        and(
          eq(signupRequestGroup.signupRequestId, id),
          eq(signupRequestGroup.groupId, group.groupId),
        ),
      );
  }
  if (complete)
    await db
      .update(signupRequest)
      .set({ status: "awaiting_handover" })
      .where(and(eq(signupRequest.id, id), eq(signupRequest.status, "provisioning")));
}

// Undefined until the request has been accepted.
export async function getProvisioningProgress(id: string) {
  const db = getDb();
  const [request] = await db
    .select({
      status: signupRequest.status,
      workspaceEmail: signupRequest.workspaceEmail,
      acceptedAt: signupRequest.acceptedAt,
      accountCreateState: signupRequest.accountCreateState,
    })
    .from(signupRequest)
    .where(eq(signupRequest.id, id));
  if (!request || !provisioningStatuses.includes(request.status)) return undefined;
  const groups = await db
    .select({
      groupId: signupRequestGroup.groupId,
      groupEmail: signupRequestGroup.groupEmail,
      role: signupRequestGroup.role,
      state: signupRequestGroup.state,
    })
    .from(signupRequestGroup)
    .where(eq(signupRequestGroup.signupRequestId, id));
  return { ...request, groups };
}
import { and, eq, inArray } from "drizzle-orm";

import { getDb } from "@/lib/db";
import { mailMessage, signupRequest, signupRequestGroup } from "@/lib/schema";

export const reviewRequestFields = {
  id: signupRequest.id,
  givenName: signupRequest.givenName,
  familyName: signupRequest.familyName,
  contactEmail: signupRequest.contactEmail,
  phone: signupRequest.phone,
  connection: signupRequest.connection,
  workspaceEmail: signupRequest.workspaceEmail,
  status: signupRequest.status,
  rejectionReason: signupRequest.rejectionReason,
  createdAt: signupRequest.createdAt,
};

// Accepted requests stay visible so their provisioning progress can be followed.
const reviewableStatuses = [
  "verified",
  "rejection_pending_notification",
  "accepted",
  "provisioning",
  "awaiting_handover",
];

export async function listReviewableSignupRequests(database = getDb) {
  return database()
    .select(reviewRequestFields)
    .from(signupRequest)
    .where(inArray(signupRequest.status, reviewableStatuses))
    .orderBy(signupRequest.createdAt);
}

export async function getReviewableSignupRequest(id: string, database = getDb) {
  const [request] = await database()
    .select(reviewRequestFields)
    .from(signupRequest)
    .where(and(eq(signupRequest.id, id), inArray(signupRequest.status, reviewableStatuses)))
    .limit(1);
  return request;
}

export type SignupRequestCorrection = Pick<
  typeof signupRequest.$inferInsert,
  "givenName" | "familyName" | "contactEmail" | "phone" | "connection"
> & { workspaceEmail?: string | null };

export async function correctVerifiedSignupRequest(
  id: string,
  correction: SignupRequestCorrection,
  database = getDb,
) {
  const [request] = await database()
    .update(signupRequest)
    .set(correction)
    .where(and(eq(signupRequest.id, id), eq(signupRequest.status, "verified")))
    .returning(reviewRequestFields);
  return request;
}

export async function beginSignupRejection(id: string, reason: string, database = getDb) {
  const [request] = await database()
    .update(signupRequest)
    .set({
      status: "rejection_pending_notification",
      rejectionReason: reason,
      rejectedAt: new Date(),
    })
    .where(and(eq(signupRequest.id, id), eq(signupRequest.status, "verified")))
    .returning(reviewRequestFields);
  return request;
}

export function rejectionMessage(reason: string) {
  return `Your Workspace signup request was not approved. Reason: ${reason}`;
}

export async function captureRejectionNotification(id: string, database = getDb) {
  return database().transaction(async (tx) => {
    const [request] = await tx
      .update(signupRequest)
      .set({ status: "rejection_pending_notification" })
      .where(
        and(eq(signupRequest.id, id), eq(signupRequest.status, "rejection_pending_notification")),
      )
      .returning({
        id: signupRequest.id,
        contactEmail: signupRequest.contactEmail,
        rejectionReason: signupRequest.rejectionReason,
      });
    if (!request?.rejectionReason) return undefined;

    await tx.insert(mailMessage).values({
      signupRequestId: request.id,
      to: request.contactEmail,
      subject: "Your Workspace signup request",
      text: rejectionMessage(request.rejectionReason),
    });
    const [completed] = await tx
      .update(signupRequest)
      .set({ status: "rejected" })
      .where(
        and(eq(signupRequest.id, id), eq(signupRequest.status, "rejection_pending_notification")),
      )
      .returning(reviewRequestFields);
    return completed;
  });
}

function nameToken(name: string) {
  return name
    .normalize("NFKD")
    .replace(/\p{M}/gu, "")
    .toLowerCase()
    .replace(/[^a-z0-9_-]/g, "");
}

export function suggestWorkspaceEmail(givenName: string, familyName: string, domain: string) {
  const given = nameToken(givenName.trim().split(/\s+/)[0] ?? "");
  const family = nameToken(familyName);
  return given && family ? `${given}.${family}@${domain.toLowerCase()}` : "";
}

export type PlannedGroup = {
  groupId: string;
  groupEmail: string;
  role: "member" | "manager" | "owner";
};

export async function getSignupPlan(id: string, database = getDb) {
  const [request] = await database()
    .select({ workspaceEmail: signupRequest.workspaceEmail })
    .from(signupRequest)
    .where(eq(signupRequest.id, id));
  const groups = await database()
    .select({
      groupId: signupRequestGroup.groupId,
      groupEmail: signupRequestGroup.groupEmail,
      role: signupRequestGroup.role,
    })
    .from(signupRequestGroup)
    .where(eq(signupRequestGroup.signupRequestId, id));
  return { workspaceEmail: request?.workspaceEmail ?? null, groups };
}

// Throws a unique violation (23505) when another active request already plans this address.
export async function saveSignupPlan(
  id: string,
  plan: { workspaceEmail: string; groups: PlannedGroup[] },
  database = getDb,
) {
  return database().transaction(async (tx) => {
    const [request] = await tx
      .update(signupRequest)
      .set({ workspaceEmail: plan.workspaceEmail })
      .where(and(eq(signupRequest.id, id), eq(signupRequest.status, "verified")))
      .returning({ id: signupRequest.id });
    if (!request) return false;
    await tx.delete(signupRequestGroup).where(eq(signupRequestGroup.signupRequestId, id));
    if (plan.groups.length)
      await tx
        .insert(signupRequestGroup)
        .values(plan.groups.map((group) => ({ ...group, signupRequestId: id })));
    return true;
  });
}
import { sql } from "drizzle-orm";
import {
  boolean,
  index,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

export const user = pgTable("auth_user", {
  id: text().primaryKey(),
  name: text().notNull(),
  email: text().notNull().unique(),
  emailVerified: boolean("email_verified").notNull(),
  image: text(),
  createdAt: timestamp("created_at").notNull(),
  updatedAt: timestamp("updated_at").notNull(),
});

export const session = pgTable(
  "auth_session",
  {
    id: text().primaryKey(),
    expiresAt: timestamp("expires_at").notNull(),
    token: text().notNull().unique(),
    createdAt: timestamp("created_at").notNull(),
    updatedAt: timestamp("updated_at").notNull(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
  },
  (table) => [index("session_user_idx").on(table.userId)],
);

export const account = pgTable(
  "auth_account",
  {
    id: text().primaryKey(),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: timestamp("access_token_expires_at"),
    refreshTokenExpiresAt: timestamp("refresh_token_expires_at"),
    scope: text(),
    password: text(),
    createdAt: timestamp("created_at").notNull(),
    updatedAt: timestamp("updated_at").notNull(),
  },
  (table) => [
    index("account_user_idx").on(table.userId),
    uniqueIndex("account_provider_subject_idx").on(table.providerId, table.accountId),
  ],
);

export const verification = pgTable(
  "auth_verification",
  {
    id: text().primaryKey(),
    identifier: text().notNull(),
    value: text().notNull(),
    expiresAt: timestamp("expires_at").notNull(),
    createdAt: timestamp("created_at").notNull(),
    updatedAt: timestamp("updated_at").notNull(),
  },
  (table) => [uniqueIndex("verification_identifier_idx").on(table.identifier)],
);

// Immutable Google and Directory identifiers, not a profile or local role copy.
export const workspaceIdentity = pgTable("workspace_identity", {
  googleSubject: text("google_subject").primaryKey(),
  directoryId: text("directory_id").notNull().unique(),
});

export const signupRequest = pgTable(
  "signup_request",
  {
    id: uuid().defaultRandom().primaryKey(),
    givenName: text("given_name").notNull(),
    familyName: text("family_name").notNull(),
    contactEmail: text("contact_email").notNull(),
    phone: text(),
    connection: text(),
    status: text().notNull().default("pending_verification"),
    rejectionReason: text("rejection_reason"),
    rejectedAt: timestamp("rejected_at", { withTimezone: true }),
    workspaceEmail: text("workspace_email"),
    acceptedAt: timestamp("accepted_at", { withTimezone: true }),
    // Directory id of the acting administrator who accepted the request.
    approvedByDirectoryId: text("approved_by_directory_id"),
    // not_started -> attempting -> created | uncertain. `attempting` left behind is uncertain too.
    accountCreateState: text("account_create_state").notNull().default("not_started"),
    googleUserId: text("google_user_id"),
    verificationTokenHash: text("verification_token_hash").notNull(),
    verificationExpiresAt: timestamp("verification_expires_at", { withTimezone: true }).notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    uniqueIndex("active_signup_request_contact_email_idx")
      .on(sql`lower(${table.contactEmail})`)
      .where(
        sql`${table.status} in ('pending_verification', 'verified', 'under_review', 'accepted', 'provisioning', 'awaiting_handover')`,
      ),
    uniqueIndex("active_signup_request_workspace_email_idx")
      .on(sql`lower(${table.workspaceEmail})`)
      .where(
        sql`${table.workspaceEmail} is not null and ${table.status} in ('verified', 'under_review', 'accepted', 'provisioning', 'awaiting_handover')`,
      ),
    uniqueIndex("signup_request_google_user_idx")
      .on(table.googleUserId)
      .where(sql`${table.googleUserId} is not null`),
  ],
);

// Selected groups are stored by immutable Google group id so provisioning can resume.
export const signupRequestGroup = pgTable(
  "signup_request_group",
  {
    signupRequestId: uuid("signup_request_id")
      .notNull()
      .references(() => signupRequest.id, { onDelete: "cascade" }),
    groupId: text("group_id").notNull(),
    groupEmail: text("group_email").notNull(),
    role: text().notNull().default("member"),
    // pending -> added | failed
    state: text().notNull().default("pending"),
  },
  (table) => [primaryKey({ columns: [table.signupRequestId, table.groupId] })],
);

export const mailMessage = pgTable("mail_message", {
  id: uuid().defaultRandom().primaryKey(),
  signupRequestId: uuid("signup_request_id")
    .notNull()
    .references(() => signupRequest.id, { onDelete: "cascade" }),
  to: text().notNull(),
  subject: text().notNull(),
  text: text().notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

Recover incomplete provisioning
## Parent

#1

## What to build

Deliver recovery for a partially provisioned Workspace user using the real application workflow around simulated Google group results. An administrator sees durable progress, safely retries unfinished work, and deliberately revises unavailable assignments while retaining successful memberships.

## Acceptance criteria

- [ ] A partial group-provisioning failure preserves the created account and every successful membership.
- [ ] An authorized administrator can retry only unfinished provisioning operations without duplicating successful work.
- [ ] An unavailable or unmanageable unfinished group can be explicitly removed or replaced with a recorded, confirmed revision.
- [ ] The workflow reaches Awaiting handover only after all currently selected memberships succeed.

## Blocked by

